const msg = $json.messages?.[0];
const contact = $json.contacts?.[0];
if (!msg) return [];
const type = msg.type;
return [{ json: {
  from: msg.from,
  wa_phone_id: $json.metadata?.phone_number_id || '',
  name: contact?.profile?.name || '',
  message_id: msg.id,
  type,
  text: type === 'text' ? msg.text.body : (msg.image?.caption || ''),
  image_id: type === 'image' ? msg.image.id : null,
  is_photo: type === 'image'
}}];

const bin = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = bin.toString('base64');
const mime = $input.first().binary.data.mimeType || 'image/jpeg';

const PROMPT = 'You are a pharmacy assistant in Egypt. Extract EVERY medicine the customer is asking for (from the text or the prescription image). Names may be Arabic or English; return the Latin brand/generic name. Return ONLY JSON: {"items":[{"name":"","strength":"","quantity":1}]}. If no medicine is found return {"items":[]}.';

return [{ json: { body: {
  contents: [{ role: 'user', parts: [
    { text: PROMPT },
    { inline_data: { mime_type: mime, data: b64 } }
  ]}],
  generationConfig: { responseMimeType: 'application/json' }
}}}];

const j = $input.first().json;
const msg = j.text || j.body || j.message || '';

const PROMPT = 'You are a pharmacy assistant in Egypt. Extract EVERY medicine the customer is asking for. Names may be Arabic or English; return the Latin brand/generic name. Return ONLY JSON: {"items":[{"name":"","strength":"","quantity":1}]}. If no medicine is found return {"items":[]}. Customer message: ' + msg;

return [{ json: { body: {
  contents: [{ role: 'user', parts: [{ text: PROMPT }] }],
  generationConfig: { responseMimeType: 'application/json' }
}}}];

