const parts = $('AI Read Request').first().json.candidates?.[0]?.content?.parts || [];
const raw = parts.map(p => p.text || '').join('') || '{}';
let items = [];
try { items = JSON.parse(raw.replace(/```json|```/g, '').trim()).items || []; } catch (e) {}

const ctx = $('Normalize Message').first().json;
const catalog = $('Read Catalog').all().map(i => i.json);
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]/g, '');

const matches = items.map(it => {
  const n = norm(it.name);
  const qty = Number(it.quantity) || 1;
  let found = catalog.filter(c => n && (norm(c.name).includes(n) || n.includes(norm(c.name)) || norm(c.active_ingredient).includes(n)));
  const st = norm(it.strength);
  if (st && found.length > 1) {
    const byStrength = found.filter(c => norm(c.strength) === st);
    if (byStrength.length) found = byStrength;
  }
  const c = found[0];
  if (!c) return { requested: it.name, qty, status: 'not_found' };
  const stock = Number(c.stock) || 0;
  return {
    requested: it.name, qty,
    sku: c.sku, name: c.name, strength: c.strength, form: c.form,
    price_egp: Number(c.price_egp), stock,
    controlled: String(c.controlled).toLowerCase() === 'yes',
    total_egp: Number(c.price_egp) * qty,
    status: stock <= 0 ? 'out_of_stock' : (stock < qty ? 'low_stock' : 'ok')
  };
});

const found = matches.filter(m => m.status !== 'not_found');
const foundCount = found.length;
const needsPharmacist = matches.some(m => m.status !== 'ok' || m.controlled);
const route = foundCount === 0 ? 'nothing_found' : (needsPharmacist ? 'pharmacist' : 'auto');

const lines = found.map(m => ({
  sku: m.sku,
  name: m.name,
  qty: m.qty,
  unit_price: m.price_egp,
  stock_before: m.stock,
  note: m.status === 'ok' ? '' : m.status
}));

return [{ json: {
  ...ctx,
  res_id: 'R-' + Date.now(),
  customer_id: ctx.from,
  customer_name: ctx.name,
  matches,
  lines,
  route
}}];

const d = $json;
const status = d.route === 'auto' ? 'confirmed' : 'pending';
const expires = new Date(Date.now() + 24 * 3600 * 1000).toISOString();
return d.lines.map(l => ({ json: {
  res_id: d.res_id,
  created_at: new Date().toISOString(),
  customer_id: d.customer_id,
  wa_phone_id: d.wa_phone_id,
  customer_name: d.customer_name,
  sku: l.sku,
  name: l.name,
  qty: l.qty,
  total_egp: l.unit_price * l.qty,
  status,
  expires_at: expires,
  pharmacist: '',
  note: l.note,
  stock_before: l.stock_before,
  route: d.route
}}));

