return $('One Row per Medicine').all().map(i => ({ json: {
  sku: i.json.sku,
  stock: Number(i.json.stock_before) - Number(i.json.qty)
}}));

const cq = $json.callback_query;
if (!cq) return [];
const [action, res_id] = (cq.data || '').split(':');
return [{ json: {
  action, res_id,
  query_id: cq.id,
  chat_id: cq.message.chat.id,
  message_id: cq.message.message_id,
  pharmacist: cq.from.first_name
}}];

const d = $('Parse Decision').first().json;
const lines = $('Find Pending Lines').all().map(i => i.json)
  .filter(l => l.res_id === d.res_id && l.status === 'pending');
const catalog = $input.all().map(i => i.json);

if (!['approve', 'reject'].includes(d.action) || !lines.length) {
  return [{ json: { ...d, ok: false, approved: false, reason: 'Already handled or request not found.' } }];
}
const approved = d.action === 'approve';
const problems = [];
const stockRows = [];
if (approved) {
  for (const l of lines) {
    const c = catalog.find(x => String(x.sku) === String(l.sku));
    if (!c) { problems.push(l.name + ': not in catalog (handle manually)'); continue; }
    if (Number(c.stock) < Number(l.qty)) { problems.push(c.name + ': only ' + c.stock + ' in stock'); continue; }
    stockRows.push({ sku: c.sku, stock: Number(c.stock) - Number(l.qty) });
  }
}
const ok = problems.length === 0;
return [{ json: {
  ...d, ok, approved, reason: problems.join('; '),
  customer_id: lines[0].customer_id,
  wa_phone_id: lines[0].wa_phone_id,
  customer_name: lines[0].customer_name,
  lines: lines.map(l => ({ row_number: l.row_number, name: l.name, qty: l.qty, total_egp: l.total_egp })),
  stockRows
}}];

const d = $('Apply Decision').first().json;
return d.lines.map(l => ({ json: {
  row_number: l.row_number,
  status: d.approved ? 'approved' : 'rejected',
  pharmacist: d.pharmacist,
  expires_at: d.approved ? new Date(Date.now() + 24 * 3600 * 1000).toISOString() : ''
}}));
